package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.os.Bundle;import android.speech.SpeechRecognizer;import org.json.*;
/** Real relay/Qwen on a synthetic segment; no microphone or real lecture data is recorded. */
final class LectureChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();GoalAgentActivity a=null;LectureInterpretation session=null;String id="";try(GoalStore s=new GoalStore(i.getTargetContext())){
 id=s.create("grades","REGRESSION_LECTURE_TRANSLATION","통역 시험",0).getString("id");a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity host=a;i.check(host.relay.connected()||host.relay.restore(),"existing Qwen relay available");
 session=new LectureInterpretation(host.chat);final LectureInterpretation live=session;i.runOnMainSync(live::show);i.check(!live.listening,"no automatic microphone start");i.runOnMainSync(()->i.check(live.enqueue("The acceleration is 9.8 meters per second squared."),"synthetic segment accepted"));
 long deadline=System.currentTimeMillis()+30000;while(System.currentTimeMillis()<deadline&&live.completed.length()==0)Thread.sleep(200);i.check(live.completed.length()==1,"actual Qwen result arrived: "+live.state.getText()+" closed="+live.closed+" active="+live.working);JSONObject row=live.completed.getJSONObject(0);i.check(row.getString("model").equals("Qwen3.8-27B-abliterated-AWQ-W4A16"),"exact model");i.check(row.getString("translation").contains("9.8"),"numeric token retained");
 i.runOnMainSync(()->live.stop("시험 중지"));i.check(!live.listening&&!live.working&&live.pending.isEmpty(),"stop cancels queue");i.runOnMainSync(live::save);i.waitForIdleSync();i.check(host.chat.history.getJSONObject(host.chat.history.length()-1).getJSONArray("lectureSegments").length()==1,"source and translation saved in owning chat");i.check(live.closed,"save closes microphone UI");
 out.putString("stream","PASS "+i.checks+" lecture checks using real Qwen translation; Android recognition available="+SpeechRecognizer.isRecognitionAvailable(host)+"; microphone audio path not exercised\n");
 }catch(Throwable e){out.putString("stream","FAIL lecture checks: "+e.getClass().getSimpleName()+": "+e.getMessage()+"\n");}finally{if(session!=null&&!session.closed){final LectureInterpretation live=session;i.runOnMainSync(()->live.dialog.dismiss());}if(a!=null){final GoalAgentActivity host=a;i.runOnMainSync(host::finish);}if(!id.isEmpty())try(GoalStore s=new GoalStore(i.getTargetContext())){s.deleteGoal(id);}}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
